m.appendChild(el("p", null, esc(text)));
if (link) { var a = el("a", "opc-link", esc(label || "Learn more")); a.href = href(link); if (/^tel:/.test(link)) a.setAttribute("data-ev", "call"); m.appendChild(a); }
